# iid_process_lpdf ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`iid_process_lpdf()` works with correct inputs", {
  process_values <- c(0.1, -0.3, 0.2)
  #' @description Test that `iid_process_lpdf()` equals the sum of independent normal log densities.
  expect_equal(
    object = FIMS:::iid_process_lpdf(process_values, 0.05, log(0.4)),
    expected = sum(stats::dnorm(process_values, 0.05, 0.4, log = TRUE))
  )
})

