# ar1_process_lpdf ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`ar1_process_lpdf()` works with correct inputs", {
  process_values <- c(0.1, -0.3, 0.2, 0.4)
  process_mean <- c(0, 0, 0.1, 0.1)
  process_sd <- 0.3
  rho <- 0.6
  # Stationary AR1: Cov(x_i, x_j) = sd^2 / (1 - rho^2) * rho^|i - j|.
  covariance <- process_sd^2 / (1 - rho^2) *
    rho^abs(outer(1:4, 1:4, "-"))
  deviation <- process_values - process_mean
  mvn_lpdf <- -0.5 * (4 * log(2 * pi) +
    as.numeric(determinant(covariance)[["modulus"]]) +
    sum(deviation * solve(covariance, deviation)))
  logit_rho <- log((1 + rho) / (1 - rho))
  #' @description Test that `ar1_process_lpdf()` equals the log density of the multivariate normal with the stationary AR1 covariance.
  expect_equal(
    object = FIMS:::ar1_process_lpdf(
      process_values, process_mean, log(process_sd), logit_rho
    ),
    expected = mvn_lpdf
  )
  #' @description Test that `ar1_process_lpdf()` with rho = 0 equals `iid_process_lpdf()`.
  expect_equal(
    object = FIMS:::ar1_process_lpdf(
      process_values, process_mean, log(process_sd), 0
    ),
    expected = FIMS:::iid_process_lpdf(
      process_values, process_mean, log(process_sd)
    )
  )
})

