## IO correctness ----
test_that("`random_walk_process_lpdf()` works with correct inputs", {
  process_values <- c(1, 1.2, 0.9, 1.1)
  #' @description Test that `random_walk_process_lpdf()` scores only the year-to-year steps.
  expect_equal(
    object = FIMS:::random_walk_process_lpdf(process_values, 0, log(0.2)),
    expected = sum(stats::dnorm(diff(process_values), 0, 0.2, log = TRUE))
  )
})

